using System.Text.Json;
using System.Text.Json.Nodes;

public class DotNetMcpServer
{
    private readonly Stream _input;
    private readonly StreamWriter _output;

    public DotNetMcpServer(Stream input, Stream output)
    {
        _input = input;
        _output = new StreamWriter(output) { AutoFlush = true };
    }

    public async Task RunAsync(CancellationToken ct = default)
    {
        using var reader = new StreamReader(_input);
        while (!ct.IsCancellationRequested)
        {
            var line = await reader.ReadLineAsync(ct);
            if (string.IsNullOrWhiteSpace(line)) continue;

            var requestNode = JsonNode.Parse(line);
            var id = requestNode?["id"]?.GetValue<long>();
            var method = requestNode?["method"]?.GetValue<string>();

            var response = HandleRequest(method, requestNode?["params"], id);
            if (response != null)
            {
                await _output.WriteLineAsync(response.ToJsonString());
            }
        }
    }

    private JsonObject? HandleRequest(string? method, JsonNode? parameters, long? id)
    {
        return method switch
        {
            "initialize" => new JsonObject
            {
                ["jsonrpc"] = "2.0",
                ["id"] = id,
                ["result"] = new JsonObject
                {
                    ["protocolVersion"] = "2024-11-05",
                    ["capabilities"] = new JsonObject { ["tools"] = new JsonObject() },
                    ["serverInfo"] = new JsonObject { ["name"] = "DotNetDiagnosticsServer", ["version"] = "1.0.0" }
                }
            },
            "tools/list" => new JsonObject
            {
                ["jsonrpc"] = "2.0",
                ["id"] = id,
                ["result"] = new JsonObject
                {
                    ["tools"] = new JsonArray
                    {
                        new JsonObject
                        {
                            ["name"] = "check_database_latency",
                            ["description"] = "Pings the specified database cluster and returns latency in milliseconds.",
                            ["inputSchema"] = new JsonObject
                            {
                                ["type"] = "object",
                                ["properties"] = new JsonObject
                                {
                                    ["cluster"] = new JsonObject { ["type"] = "string", ["description"] = "Target DB cluster: primary or read_replica" }
                                },
                                ["required"] = new JsonArray { "cluster" }
                            }
                        }
                    }
                }
            },
            "tools/call" => ExecuteToolCall(parameters, id),
            _ => null
        };
    }

    private JsonObject ExecuteToolCall(JsonNode? parameters, long? id)
    {
        var toolName = parameters?["name"]?.GetValue<string>();
        var cluster = parameters?["arguments"]?["cluster"]?.GetValue<string>() ?? "primary";

        var resultText = toolName switch
        {
            "check_database_latency" => $"Cluster '{cluster}' latency is 4.2ms (healthy).",
            _ => $"Unknown tool '{toolName}'"
        };

        return new JsonObject
        {
            ["jsonrpc"] = "2.0",
            ["id"] = id,
            ["result"] = new JsonObject
            {
                ["content"] = new JsonArray
                {
                    new JsonObject { ["type"] = "text", ["text"] = resultText }
                },
                ["isError"] = false
            }
        };
    }
}
